function partsSummary(jobCard){const lists=listsForJobCard(jobCard),items=lists.flatMap(r=>Array.isArray(r.items)?r.items:[]);return {exists:lists.length>0,count:items.length,listNo:lists[0]?.listNo||null,statuses:items.map(x=>x.status||'LISTED')}}
function openForJobCard(jobCard){const jc=normalizeJobCard(jobCard),lists=listsForJobCard(jc);if(!lists.length)return {ok:false,reason:'NO_PARTS_LIST'};openList(lists[0].listNo);return {ok:true,list:lists[0]}}

async function commitEvent(event){const q=window.zukaitV2?.queue;if(!window.zukaitCloud?.v2CommitEvent||!navigator.onLine){try{q?.enqueue?.(event)}catch(_){}return {ok:false,reason:'V2_TRANSPORT_UNAVAILABLE',queued:true}}try{const r=await window.zukaitCloud.v2CommitEvent(event);return {ok:true,result:r}}catch(e){const reason=String(e?.code||e?.message||e);if(['NETWORK','TIMEOUT','NO_SESSION','Failed to fetch'].some(x=>reason.includes(x))){try{q?.enqueue?.(event)}catch(_){}return {ok:false,reason,queued:true}}return {ok:false,reason}}}
function create(jobCard){return {ok:false,reason:'SERVER_ALLOCATION_REQUIRED',jobCard:normalizeJobCard(jobCard)}}
function addItem(listNo,item){if(!canManage())return {ok:false,reason:'FORBIDDEN'};const rows=read(),r=rows.find(x=>x.listNo===listNo);if(!r)return {ok:false,reason:'LIST_NOT_FOUND'};if(r.status==='CLOSED')return {ok:false,reason:'LIST_CLOSED'};const name=String(item?.name||item?.part||'').trim();if(!name)return {ok:false,reason:'PART_REQUIRED'};const partNo=String(item?.partNo||'').trim().toUpperCase();const duplicate=r.items.find(x=>partKey(x.name,x.partNo)===partKey(name,partNo)&&x.status!=='RETURNED');if(duplicate)return {ok:false,reason:'DUPLICATE_PART',item:duplicate};const itemId='SP-'+(globalThis.crypto?.randomUUID?.()||((Date.now())+'-'+Math.random().toString(36).slice(2)));r.items.push({id:itemId,name,partNo,qty:validQty(item?.qty)||1,status:'LISTED',revision:0,createdAt:new Date().toISOString()});r.updatedAt=new Date().toISOString();write(rows);return {ok:true,list:r}}
function validQty(v){const n=Number(v);return Number.isFinite(n)&&n>0&&n<=9999?n:null}
function validMoney(v){if(v==null||v==='')return null;const n=Number(v);return Number.isFinite(n)&&n>=0&&n<=1000000?Math.round(n*1000)/1000:null}
function updateCommercial(listNo,itemId,patch={}){const u=currentUser()||{};if(!canPurchase())return {ok:false,reason:'PRICE_PERMISSION_REQUIRED'};const rows=read(),list=rows.find(x=>x.listNo===listNo);if(!list)return {ok:false,reason:'LIST_NOT_FOUND'};const item=list.items.find(x=>x.id===itemId);if(!item)return {ok:false,reason:'PART_NOT_FOUND'};if(['FITTED','CUSTOMER_SETTLEMENT'].includes(item.status))return {ok:false,reason:'PART_FINALIZED'};if(Object.prototype.hasOwnProperty.call(patch,'qty')){const q=validQty(patch.qty);if(q==null)return {ok:false,reason:'INVALID_QUANTITY'};item.qty=q}for(const k of ['price','quoteAmount','purchaseAmount','billAmount','supplierCost'])if(Object.prototype.hasOwnProperty.call(patch,k)){const n=validMoney(patch[k]);if(n==null&&patch[k]!==''&&patch[k]!=null)return {ok:false,reason:'INVALID_AMOUNT'};if(n==null)delete item[k];else item[k]=n}if(Object.prototype.hasOwnProperty.call(patch,'supplier'))item.supplier=String(patch.supplier||'').trim();item.updatedAt=new Date().toISOString();item.updatedBy=u.id||null;list.updatedAt=item.updatedAt;write(rows);return {ok:true,item}}
