function markSparePartsModal(){const m=document.getElementById('modal');if(m)m.classList.add('v2-sp-modal-host')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function reportAmount(item){for(const k of ['finalPrice','purchaseAmount','supplierCost','billAmount','price']){const n=Number(item?.[k]);if(Number.isFinite(n)&&n>=0)return n}return 0}
function reportActivityAt(item,list){const dates=[item?.updatedAt,item?.fittedAt,item?.returnedAt,item?.confirmedAt,item?.supervisorVerifiedAt,item?.receivedAt,item?.createdAt,list?.updatedAt,list?.createdAt].filter(Boolean).map(String).filter(x=>!Number.isNaN(Date.parse(x))).sort((a,b)=>Date.parse(b)-Date.parse(a));return dates[0]||''}
function reportRows(){return read().flatMap(list=>(Array.isArray(list.items)?list.items:[]).map(item=>({listNo:list.listNo,jobCard:list.jobCard,vehicle:[list.vehicle,list.model,list.year,list.registration].filter(Boolean).join(' · '),createdAt:item.createdAt||list.createdAt||'',activityAt:reportActivityAt(item,list),name:item.name||'',partNo:item.partNo||'',qty:Number(item.qty)||0,status:item.status||'LISTED',supplier:item.supplier||'',amount:reportAmount(item)})))}
function normalizeReportRow(r={}){const p=r&&typeof r.payload==='object'&&r.payload?r.payload:{};const qty=Number(r.qty??r.quantity??p.qty??p.quantity??0),amount=Number(r.amount??r.purchaseAmount??r.purchase_amount??r.supplierCost??r.supplier_cost??r.billAmount??r.bill_amount??r.price??p.amount??p.purchaseAmount??p.purchase_amount??p.supplierCost??p.supplier_cost??p.billAmount??p.bill_amount??p.price??0),partId=String(r.partId??r.part_id??p.partId??p.part_id??r.entity_id??r.entityId??''),revision=Number(r.revision??r.serverRevision??r.server_revision??p.revision??0);return {eventId:String(r.event_id??r.eventId??''),eventType:String(r.event_type??r.eventType??''),partId,listNo:String(r.listNo??r.list_no??r.partsListNo??r.parts_list_no??p.listNo??p.list_no??''),jobCard:String(r.jobCard??r.job_card??r.jobCardNo??r.job_card_no??p.jobCard??p.job_card??''),vehicle:String(r.vehicle??r.vehicle_name??p.vehicle??p.vehicle_name??[r.make??p.make,r.model??p.model,r.year??p.year,r.registration??r.reg??p.registration??p.reg].filter(Boolean).join(' · ')??''),createdAt:String(r.createdAt??r.created_at??p.createdAt??p.created_at??r.sort_time??''),activityAt:String(r.activityAt??r.activity_at??r.updatedAt??r.updated_at??p.updatedAt??p.updated_at??r.sort_time??r.createdAt??r.created_at??''),name:String(r.name??r.partName??r.part_name??r.part??p.name??p.partName??p.part_name??p.part??''),partNo:String(r.partNo??r.part_no??p.partNo??p.part_no??''),qty:Number.isFinite(qty)&&qty>=0?qty:0,status:String(r.status??p.to??p.status??'LISTED').toUpperCase(),supplier:String(r.supplier??r.supplier_name??p.supplier??p.supplier_name??''),amount:Number.isFinite(amount)&&amount>=0?Math.round(amount*1000)/1000:0,revision:Number.isFinite(revision)&&revision>=0?revision:0}}

function hydrateFromServerRows(serverRows){const local=reconcileSyncMarkers(read()),byList=new Map(local.map(x=>[String(x.listNo||''),x]));const ordered=(serverRows||[]).slice().sort((a,b)=>Date.parse(a.sort_time||a.server_time||a.activityAt||a.created_at||0)-Date.parse(b.sort_time||b.server_time||b.activityAt||b.created_at||0));for(const raw of ordered){const r=normalizeReportRow(raw),p=raw?.payload&&typeof raw.payload==='object'?raw.payload:{};if(!r.listNo)continue;let list=byList.get(r.listNo);if(!list){list={listNo:r.listNo,jobCard:r.jobCard,vehicle:r.vehicle,registration:String(p.registration||''),items:[],createdAt:r.createdAt||r.activityAt||new Date().toISOString(),serverHydrated:true};local.unshift(list);byList.set(r.listNo,list)}if(r.jobCard&&!list.jobCard)list.jobCard=r.jobCard;if(r.vehicle&&!list.vehicle)list.vehicle=r.vehicle;if(p.registration&&!list.registration)list.registration=String(p.registration);if(p.model&&!list.model)list.model=String(p.model);if(p.year&&!list.year)list.year=String(p.year);if(p.customer&&!list.customer)list.customer=String(p.customer);const id=String(r.partId||p.partId||'');if(!id||id===r.listNo)continue;let item=list.items.find(x=>String(x.id)===id);const type=String(r.eventType||'');if(type==='SPARE_PART_LISTED'&&r.name){if(!item){item={id,name:r.name,partNo:r.partNo,qty:r.qty||1,status:'LISTED',revision:0,createdAt:r.activityAt};list.items.push(item)}else if(!pendingTransition(item)){item.name=r.name;item.qty=r.qty||item.qty;item.partNo=r.partNo||item.partNo}continue}if(!item)continue;if(type==='SPARE_PART_STATUS_CHANGED'){const revision=Number(r.revision||0);if(!pendingTransition(item)&&revision>=Number(item.revision||0)){item.status=String(p.to||r.status||item.status);item.revision=revision;item.updatedAt=r.activityAt||item.updatedAt;if(p.to==='RETURNED'||p.to==='ORDERED'){delete item.arrivalAccepted;delete item.arrivalAcceptedAt}if(p.to==='RECEIVED'){item.receivedQty=Number(item.qty)||1;item.receivedAt=r.activityAt}if(p.to==='SUPERVISOR_VERIFIED')item.supervisorVerifiedAt=r.activityAt;if(p.to==='SUPERVISOR_CONFIRMED')item.confirmedAt=r.activityAt;if(p.reason)item.returnReason=String(p.reason)}continue}if(type==='SPARE_PART_COMMERCIAL_UPDATED'){const rev=Number(r.revision||0);if(rev>=Number(item.commercialRevision||0)){if(Object.prototype.hasOwnProperty.call(p,'quoteAmount'))item.quoteAmount=p.quoteAmount;if(Object.prototype.hasOwnProperty.call(p,'purchaseAmount'))item.purchaseAmount=p.purchaseAmount;if(Object.prototype.hasOwnProperty.call(p,'supplier'))item.supplier=String(p.supplier||'');item.commercialRevision=rev}continue}if(type==='SPARE_PART_ARRIVAL_ACCEPTED'){item.arrivalAccepted=true;item.arrivalAcceptedAt=r.activityAt;continue}if(type==='SPARE_PART_FINAL_PRICE_RECORDED'){const rev=Number(r.revision||0);if(rev>=Number(item.finalPriceRevision||0)){const amount=validMoney(p.finalPrice);if(amount!=null){item.finalPrice=amount;item.finalPriceRevision=rev}}continue}if(type==='SPARE_PART_ITEM_EDITED'&&p.after&&Number(r.revision||0)>=Number(item.editRevision||0)){Object.assign(item,p.after);item.editRevision=Number(r.revision||0)}}write(local);return local}
async function hydrateAuthoritativeLists(){reconcileSyncMarkers();if(!navigator.onLine||!window.zukaitV2?.reports?.page)return read();try{let cursor=null,rows=[],pages=0;do{const r=await window.zukaitV2.reports.page('SPARE_PARTS',{cursor,limit:500,filters:{}});if(!Array.isArray(r?.rows)||r.source==='server-required')return read();rows.push(...r.rows);cursor=r.nextCursor??null;pages++}while(cursor&&pages<20);return hydrateFromServerRows(rows)}catch(_){return read()}}
async function loadAuthoritativeManagerReport(){if(role()!=='Manager')return {rows:[],source:'forbidden'};const svc=window.zukaitV2?.reports;if(!navigator.onLine||!svc?.page)return {rows:reportRows(),source:'local-fallback'};try{let cursor=null,rows=[],source='server',pages=0;do{const r=await svc.page('SPARE_PARTS',{cursor,limit:500,filters:{}});if(!Array.isArray(r?.rows)||r.source==='server-required')return {rows:reportRows(),source:'local-fallback'};rows.push(...r.rows.map(normalizeReportRow));source=r.source||source;cursor=r.nextCursor??null;pages++}while(cursor&&pages<20);return {rows,source:cursor?'server-capped-10000':source}}catch(_){return {rows:reportRows(),source:'local-fallback'}}}
let managerReportSourceRows=null,managerReportSource='local-fallback';
async function openManagerReport(){ensureSparePartsUiStyle();if(role()!=='Manager'){alert('Manager access required.');return}const loaded=await loadAuthoritativeManagerReport();managerReportSourceRows=loaded.rows;managerReportSource=loaded.source;window.openModal(withNav('<h3>📊 Spare Parts Report</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><label>From<input id="v2SpReportFrom" type="date"></label><label>To<input id="v2SpReportTo" type="date"></label></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px"><input id="v2SpReportSearch" placeholder="JC / PL / vehicle / part"><select id="v2SpReportStatus"><option value="">All statuses</option>'+((window.zukaitV2?.spareParts?.STATUS)||[]).map(s=>'<option>'+esc(s)+'</option>').join('')+'</select></div><button onclick="zukaitV2.sparePartsMain.renderManagerReport()" style="'+spareBtn('primary')+';margin-top:8px">Apply</button><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><button onclick="zukaitV2.sparePartsMain.printManagerReport()" style="'+spareBtn('primary')+'">🖨 Print / PDF</button><button onclick="zukaitV2.sparePartsMain.whatsAppManagerReport()" style="'+spareBtn('success')+'">WhatsApp</button><button onclick="zukaitV2.sparePartsMain.shareManagerReport()" style="'+spareBtn('info')+'">↗ Share</button><button onclick="zukaitV2.sparePartsMain.open()" style="'+spareBtn('neutral')+'">← Back</button></div><div id="v2SpReportBody"></div>'));renderManagerReport()}
function managerReportFilters(){return {from:document.getElementById('v2SpReportFrom')?.value||'',to:document.getElementById('v2SpReportTo')?.value||'',q:String(document.getElementById('v2SpReportSearch')?.value||'').trim().toLowerCase(),status:document.getElementById('v2SpReportStatus')?.value||''}}
function filteredReportRows(){const f=managerReportFilters();const base=Array.isArray(managerReportSourceRows)?managerReportSourceRows:reportRows();return base.filter(r=>{const day=String(r.activityAt||r.createdAt||'').slice(0,10);if(f.from&&(!day||day<f.from))return false;if(f.to&&(!day||day>f.to))return false;if(f.status&&r.status!==f.status)return false;if(f.q&&!([r.listNo,r.jobCard,r.vehicle,r.name,r.partNo,r.supplier].join(' ').toLowerCase().includes(f.q)))return false;return true})}
function managerReportText(){const rows=filteredReportRows(),f=managerReportFilters();const range=[f.from?('From '+f.from):'',f.to?('To '+f.to):'',f.status?('Status '+f.status):'',f.q?('Search '+f.q):''].filter(Boolean).join(' | ');const lines=['ZUKAIT INTERNATIONAL LLC','SPARE PARTS REPORT',range,''];rows.forEach(r=>lines.push([r.listNo,'JC '+r.jobCard,r.vehicle,r.name,'Qty '+r.qty,r.status,r.supplier,r.amount.toFixed(3)+' OMR'].filter(Boolean).join(' | ')));return lines.join('\n')}
function printManagerReport(){if(role()!=='Manager')return;const body=document.getElementById('v2SpReportBody');if(!body)return;const w=window.open('','_blank');if(!w){alert('Print window blocked.');return}w.document.write('<!doctype html><html><head><title>Spare Parts Report</title><style>body{font-family:Arial;padding:20px;color:#111}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:6px;text-align:left}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.notice{border:1px solid #ddd;padding:8px}.stat{font-size:20px;font-weight:bold}.pill{display:inline-block;padding:4px 7px;border:1px solid #bbb;margin:2px}.small{font-size:11px}</style></head><body><h2>Zukait International LLC</h2><h3>Spare Parts Report</h3>'+body.innerHTML+'</body></html>');w.document.close();w.focus();w.print()}
function whatsAppReportText(){const rows=filteredReportRows(),f=managerReportFilters(),max=40,shown=rows.slice(0,max),qty=rows.reduce((a,r)=>a+r.qty,0),amount=Math.round(rows.reduce((a,r)=>a+r.amount,0)*1000)/1000;const range=[f.from?('From '+f.from):'',f.to?('To '+f.to):'',f.status?('Status '+f.status):'',f.q?('Search '+f.q):''].filter(Boolean).join(' | ');const lines=['ZUKAIT INTERNATIONAL LLC','SPARE PARTS REPORT',range,'Parts Lists: '+new Set(rows.map(r=>r.listNo)).size+' | Part Lines: '+rows.length+' | Total Qty: '+qty+' | Recorded Amount: '+amount.toFixed(3)+' OMR',''];shown.forEach(r=>lines.push([r.listNo,'JC '+r.jobCard,r.name,'Qty '+r.qty,r.status].filter(Boolean).join(' | ')));if(rows.length>max)lines.push('... '+(rows.length-max)+' more part line(s). Use Print / PDF for the complete report.');return lines.join('\n')}
function whatsAppManagerReport(){if(role()!=='Manager')return;const text=whatsAppReportText(),url='https://wa.me/?text='+encodeURIComponent(text);try{const w=window.open(url,'_blank');if(w)return}catch(_){}window.location.href=url}
async function shareManagerReport(){if(role()!=='Manager')return;const text=managerReportText();try{if(navigator.share){await navigator.share({title:'Spare Parts Report',text});return}}catch(e){if(e?.name==='AbortError')return}try{await navigator.clipboard.writeText(text);alert('Spare Parts report copied. You can share it from this device.')}catch(_){alert('Share is not available on this device. Use Print / PDF.')}}
function renderManagerReport(){if(role()!=='Manager')return;const rows=filteredReportRows();const qty=rows.reduce((a,r)=>a+r.qty,0),cost=Math.round(rows.reduce((a,r)=>a+r.amount,0)*1000)/1000,fittedQty=rows.filter(r=>r.status==='FITTED').reduce((a,r)=>a+r.qty,0),returnedQty=rows.filter(r=>r.status==='RETURNED').reduce((a,r)=>a+r.qty,0),unavailableQty=rows.filter(r=>r.status==='UNAVAILABLE').reduce((a,r)=>a+r.qty,0),statuses={};rows.forEach(r=>statuses[r.status]=(statuses[r.status]||0)+1);const sourceNote='<div class="notice"><b>Data source:</b> '+esc(managerReportSource==='local-fallback'?'Local fallback — server report unavailable':managerReportSource)+'</div>';const summary=sourceNote+'<div class="grid" style="margin-top:10px"><div class="notice"><b>Parts Lists</b><div class="stat">'+new Set(rows.map(r=>r.listNo)).size+'</div></div><div class="notice"><b>Part Lines</b><div class="stat">'+rows.length+'</div></div><div class="notice"><b>Total Qty</b><div class="stat">'+qty+'</div></div><div class="notice"><b>Recorded Amount</b><div class="stat">'+cost.toFixed(3)+' OMR</div><span class="small">Uses stored commercial amounts without assuming unit vs line pricing.</span></div><div class="notice"><b>Fitted Qty</b><div class="stat">'+fittedQty+'</div></div><div class="notice"><b>Returned Qty</b><div class="stat">'+returnedQty+'</div></div><div class="notice"><b>Unavailable Qty</b><div class="stat">'+unavailableQty+'</div></div></div>';const st=Object.entries(statuses).map(([s,n])=>'<span class="pill">'+esc(s)+' '+n+'</span>').join('');const table=rows.length?'<div style="overflow:auto"><table><thead><tr><th>Activity Date</th><th>PL</th><th>JC</th><th>Vehicle</th><th>Part</th><th>Qty</th><th>Status</th><th>Supplier</th><th>Recorded Amount OMR</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(String(r.activityAt||r.createdAt||'').slice(0,10))+'</td><td>'+esc(r.listNo)+'</td><td>'+esc(r.jobCard)+'</td><td>'+esc(r.vehicle)+'</td><td>'+esc(r.name)+(r.partNo?'<div class="small">'+esc(r.partNo)+'</div>':'')+'</td><td>'+r.qty+'</td><td>'+esc(r.status)+'</td><td>'+esc(r.supplier)+'</td><td>'+r.amount.toFixed(3)+'</td></tr>').join('')+'</tbody></table></div>':'<p class="muted">No matching Spare Parts records.</p>';const body=document.getElementById('v2SpReportBody');if(body)body.innerHTML=summary+'<div style="margin:8px 0">'+st+'</div>'+table}
let purchaserActiveTab='NEW',purchaserQuery='';
function purchaserItemRows(rows=read()){return rows.flatMap(list=>(list.items||[]).map(item=>({list,item})))}
function purchaserTabFor(item){const status=String(item.status||'LISTED');if(['LISTED','ENQUIRY','RETURNED','UNAVAILABLE'].includes(status)||item.syncConflict)return 'NEW';if(['QUOTED','ORDERED'].includes(status)||(['RECEIVED','SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED'].includes(status)&&!item.arrivalAccepted)||pendingTransition(item))return 'PROGRESS';return 'HISTORY'}
function purchaserCard(list,item){const action=nextActionFor(item,'Purchaser'),blocked=!!item.syncConflict||pendingTransition(item),status=String(item.status||'LISTED');const next=blocked?'<span class="v2-sp-pending">'+(item.syncConflict?'⚠ Sync conflict':'⟳ Pending sync')+'</span>':action?'<button type="button" style="'+spareBtn(action[2])+'" onclick="zukaitV2.sparePartsMain.purchaserAdvance(\''+esc(list.listNo)+'\',\''+esc(item.id)+'\',\''+esc(action[1])+'\')">'+esc(action[0])+' →</button>':'<span class="v2-sp-pending">Waiting for Supervisor</span>';return '<article class="v2-sp-purchase-card"><div class="v2-sp-purchase-head"><div><strong>'+esc(item.name||'Part')+'</strong><small>'+esc(list.listNo)+' · JC '+esc(list.jobCard)+' · '+esc([list.vehicle,list.registration].filter(Boolean).join(' · '))+'</small></div><span style="background:'+statusColour(status)+'">'+esc(status.replace(/_/g,' '))+'</span></div><div class="v2-sp-purchase-facts"><span>Qty <b>'+esc(item.qty||1)+'</b></span><span>Supplier <b>'+esc(item.supplier||'—')+'</b></span><span>Quote <b>'+(item.quoteAmount==null?'—':esc(Number(item.quoteAmount).toFixed(3))+' OMR')+'</b></span></div><div class="v2-sp-purchase-actions">'+next+'<button type="button" class="v2-sp-purchase-edit" onclick="zukaitV2.sparePartsMain.openPurchaserItem(\''+esc(list.listNo)+'\',\''+esc(item.id)+'\')">Edit details</button><button type="button" class="v2-sp-purchase-edit" onclick="zukaitV2.sparePartsMain.openList(\''+esc(list.listNo)+'\')">Full list / WhatsApp</button></div></article>'}
function purchaserTab(tab='NEW'){if(role()!=='Purchaser')return;purchaserActiveTab=['NEW','PROGRESS','HISTORY'].includes(tab)?tab:'NEW';const items=purchaserItemRows(),counts={NEW:0,PROGRESS:0,HISTORY:0};items.forEach(x=>counts[purchaserTabFor(x.item)]++);const tabs=[['NEW','New / Problems'],['PROGRESS','In Progress'],['HISTORY','History']].map(([key,label])=>'<button type="button" class="'+(purchaserActiveTab===key?'active':'')+'" onclick="zukaitV2.sparePartsMain.purchaserTab(\''+key+'\')">'+label+' <b>'+counts[key]+'</b></button>').join('');const q=purchaserQuery.trim().toLowerCase(),matches=items.filter(x=>purchaserTabFor(x.item)===purchaserActiveTab&&(!q||[x.list.listNo,x.list.jobCard,x.list.vehicle,x.list.registration,x.item.name,x.item.partNo,x.item.supplier].some(v=>String(v||'').toLowerCase().includes(q)))).sort((a,b)=>Number(!!b.item.syncConflict)-Number(!!a.item.syncConflict)||Number(['RETURNED','UNAVAILABLE'].includes(b.item.status))-Number(['RETURNED','UNAVAILABLE'].includes(a.item.status))||Date.parse(b.item.updatedAt||b.list.createdAt||0)-Date.parse(a.item.updatedAt||a.list.createdAt||0));const host=document.getElementById('v2SpPurchaserTabs'),body=document.getElementById('v2SpPurchaserItems');if(host)host.innerHTML=tabs;if(body)body.innerHTML=matches.length?matches.slice(0,200).map(x=>purchaserCard(x.list,x.item)).join(''):'<p class="muted">No matching parts in this tab.</p>'}
function purchaserSearch(){purchaserQuery=String(document.getElementById('v2SpPurchaserSearch')?.value||'');purchaserTab(purchaserActiveTab)}
async function renderPurchaserDashboard(){ensureSparePartsUiStyle();await hydrateAuthoritativeLists();const styleId='v2SpPurchaserFlowStyle';if(!document.getElementById(styleId)){const st=document.createElement('style');st.id=styleId;st.textContent='.v2-sp-purchaser-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:12px 0}.v2-sp-purchaser-tabs button{min-height:52px;margin:0;padding:7px 3px;background:#e9f1fa;color:#24415f;border:1px solid #cdddec;font-size:12px;font-weight:800}.v2-sp-purchaser-tabs button.active{background:#2563eb;color:#fff}.v2-sp-purchase-card{background:#fff;border:1px solid #dbe5f0;border-left:4px solid #2563eb;border-radius:15px;padding:12px;margin:9px 0;box-shadow:0 5px 16px #17304d12}.v2-sp-purchase-head{display:flex;justify-content:space-between;gap:8px}.v2-sp-purchase-head strong{font-size:16px;color:#17304d}.v2-sp-purchase-head small{display:block;margin-top:4px;color:#536b84}.v2-sp-purchase-head>span{align-self:flex-start;padding:5px 7px;border-radius:8px;color:#fff;font-size:11px;font-weight:800}.v2-sp-purchase-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin:11px 0}.v2-sp-purchase-facts span{padding:7px;background:#f3f7fb;border-radius:8px;font-size:11px;color:#526579}.v2-sp-purchase-facts b{display:block;color:#17304d;overflow-wrap:anywhere}.v2-sp-purchase-actions{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:6px;align-items:center}.v2-sp-purchase-actions button{margin:0}.v2-sp-purchase-edit{background:#eef2f7;color:#24415f;border:1px solid #d6e1ee;font-weight:800;min-height:44px}.v2-sp-pending{color:#79550f;font-weight:800}@media(max-width:600px){.v2-sp-purchase-actions{grid-template-columns:1fr 1fr}.v2-sp-purchase-actions>button:first-child{grid-column:1/-1}}@media(max-width:400px){.v2-sp-purchase-facts{grid-template-columns:1fr 1fr}.v2-sp-purchase-actions{grid-template-columns:1fr}.v2-sp-purchase-edit{width:100%}}';document.head.appendChild(st)}window.openModal(withNav('<div class="v2-sp-purchaser v2-sp-dashboard"><h3 style="margin:0">🛒 Purchasing</h3><small>Choose a part, then take its next step.</small><div class="v2-sp-grid2" style="margin-top:12px"><button type="button" onclick="zukaitV2.sparePartsMain.managerBucket(&quot;WAITING&quot;)" style="'+dashboardTile('wait')+'">⏳ Parts Waiting</button><button type="button" onclick="zukaitV2.sparePartsMain.managerBucket(&quot;PURCHASE_COMPLETED&quot;)" style="'+dashboardTile('success')+'">✅ Purchase Completed</button></div><div class="v2-sp-search" style="margin-top:12px"><input id="v2SpPurchaserSearch" type="search" placeholder="Search JC / PL / registration / part" value="'+esc(purchaserQuery)+'" oninput="zukaitV2.sparePartsMain.purchaserSearch()"><button type="button" class="blue" onclick="zukaitV2.sparePartsMain.purchaserSearch()">Search</button></div><button type="button" onclick="zukaitV2.sparePartsMain.openPartsQuotation()" style="'+spareBtn('edit')+';width:100%;margin-top:12px">🧾 Parts Quotation · Search Parts List</button><div id="v2SpPurchaserTabs" class="v2-sp-purchaser-tabs"></div><div id="v2SpPurchaserItems"></div></div>'));markSparePartsModal();purchaserTab(purchaserActiveTab)}

async function openPartsQuotation(){if(role()!=='Purchaser')return;await hydrateAuthoritativeLists();window.openModal(withNav('<div class="v2-sp-purchaser v2-sp-dashboard"><h3>Parts Quotation</h3><label>Find Parts List by PL, JC or registration<input id="v2SpQuotationSearch" type="search" placeholder="PL001 / JC120 / registration" oninput="zukaitV2.sparePartsMain.findPartsQuotation()"></label><div id="v2SpQuotationResults"></div></div>','zukaitV2.sparePartsMain.open()'));markSparePartsModal();findPartsQuotation()}
function findPartsQuotation(){const q=String(document.getElementById('v2SpQuotationSearch')?.value||'').trim().toLowerCase(),host=document.getElementById('v2SpQuotationResults');if(!host)return;const matching=read().filter(r=>(r.items||[]).length&&(!q||[r.listNo,r.jobCard,r.registration,r.vehicle,r.model,r.year].some(v=>String(v||'').toLowerCase().includes(q)))).slice(0,50);host.innerHTML=matching.map(r=>'<button type="button" data-list="'+esc(r.listNo)+'" onclick="zukaitV2.sparePartsMain.quotationListClick(this)" style="'+spareBtn('primary')+';display:block;width:100%;text-align:left;margin:7px 0">'+esc(r.listNo)+' · JC '+esc(r.jobCard)+' · '+esc([r.vehicle,r.model,r.year].filter(Boolean).join(' '))+'<small style="display:block">'+esc(r.registration||'')+' · '+r.items.length+' parts</small></button>').join('')||'<p class="muted">No matching Parts List found.</p>'}
function quotationListClick(button){const no=button?.dataset?.list;if(no)openQuotationList(no)}
function openQuotationList(no){if(role()!=='Purchaser')return;const list=read().find(x=>x.listNo===no);if(!list)return;const rows=(list.items||[]).map((item,i)=>'<tr style="border-bottom:1px solid #dbe5f0"><td>'+(i+1)+'</td><td>'+esc(item.name)+'</td><td>'+esc(item.qty||1)+'</td><td><input type="number" min="0" step="0.001" value="'+esc(item.quoteAmount??'')+'" placeholder="OMR" id="v2SpQuote_'+i+'" aria-label="Price for '+esc(item.name)+'" style="width:98px;min-height:44px"></td><td><button type="button" data-list="'+esc(no)+'" data-item="'+esc(item.id)+'" data-index="'+i+'" onclick="zukaitV2.sparePartsMain.saveQuotationPrice(this)" style="'+spareBtn('success')+'">Save</button></td></tr>').join('');window.openModal(withNav('<div class="v2-sp-purchaser v2-sp-dashboard"><h3>Parts Quotation · '+esc(no)+'</h3><p>'+esc([list.vehicle,list.model,list.year].filter(Boolean).join(' '))+' · JC '+esc(list.jobCard)+' · Reg '+esc(list.registration||'—')+'</p><div style="overflow-x:auto"><table style="width:100%;text-align:left;min-width:440px"><thead><tr><th>No.</th><th>Part</th><th>Qty</th><th>Price OMR</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div><p id="v2SpQuoteMessage" role="status" aria-live="polite"></p></div>','zukaitV2.sparePartsMain.openPartsQuotation()'));markSparePartsModal()}
async function saveQuotationPrice(button){if(role()!=='Purchaser'||!button)return;const no=button.dataset.list,id=button.dataset.item,index=button.dataset.index,field=document.getElementById('v2SpQuote_'+index),message=document.getElementById('v2SpQuoteMessage'),value=field?.value,amount=validMoney(value);if(amount==null){if(message)message.textContent='Enter a valid price in OMR.';return}const rows=read(),list=rows.find(x=>x.listNo===no),item=list?.items?.find(x=>x.id===id);if(!item||item.syncConflict||pendingTransition(item))return;if(Number(item.quoteAmount)===amount&&item.quoteAmount!=null){if(message)message.textContent='Price already saved.';return}const previous={...item},rev=Number(item.commercialRevision||0)+1;button.disabled=true;const updated=updateCommercial(no,id,{quoteAmount:amount});if(!updated.ok){button.disabled=false;if(message)message.textContent=updated.reason;return}const latest=read(),next=latest.find(x=>x.listNo===no)?.items?.find(x=>x.id===id);if(next)next.commercialRevision=rev;write(latest);const synced=await commitEvent({eventId:'spare-commercial-'+id+'-'+rev,entityId:id,actorId:currentUser()?.id||null,type:'SPARE_PART_COMMERCIAL_UPDATED',serverRevision:rev,payload:{partId:id,listNo:no,jobCard:list.jobCard,supplier:next?.supplier||'',quoteAmount:amount,purchaseAmount:next?.purchaseAmount??null}});if(!synced.ok&&!synced.queued){const rollback=read(),old=rollback.find(x=>x.listNo===no)?.items?.find(x=>x.id===id);if(old)Object.assign(old,previous);write(rollback);button.disabled=false;if(message)message.textContent='Could not save price: '+synced.reason;return}button.disabled=false;if(message)message.textContent='Price saved for '+item.name+'.'}
function managerDashboardSummary(rows=read()){const items=rows.flatMap(l=>(l.items||[]).map(i=>Object.assign({list:l},i))),problemStatuses=new Set(['RETURNED','UNAVAILABLE']),waitingStatuses=new Set(['ORDERED']),finalStatuses=new Set(['RECEIVED','SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED']);const attention=items.filter(i=>problemStatuses.has(i.status)||i.cashSettlementRequired).length,waiting=rows.filter(r=>managerListMatches(r,'WAITING')).length,deliveredPending=rows.filter(r=>r.vehicleDeliveredPartsPending===true||r.deliveryPartsPending===true||r.deliveredPendingParts===true||String(r.status||'').toUpperCase()==='DELIVERED_PENDING').length,purchaseCompleted=rows.filter(r=>(r.items||[]).length>0&&(r.items||[]).every(i=>finalStatuses.has(i.status))).length,now=new Date(),from=new Date(now.getFullYear(),now.getMonth(),1).getTime(),to=new Date(now.getFullYear(),now.getMonth()+1,1).getTime(),monthSpend=items.reduce((sum,i)=>{const t=Date.parse(i.updatedAt||i.receivedAt||i.createdAt||0);return t>=from&&t<to?sum+reportAmount(i):sum},0);return {attention,waiting,deliveredPending,purchaseCompleted,monthSpend:Math.round(monthSpend*1000)/1000,totalLists:rows.length}}
const DRAFT_KEY='zukait_v2_parts_create_draft_v1';
function draftRead(){try{return JSON.parse(localStorage.getItem(DRAFT_KEY)||'{}')}catch(_){return {}}}
function draftSave(d){localStorage.setItem(DRAFT_KEY,JSON.stringify(d))}
function draftMessage(message){const el=document.getElementById('v2SpDraftMessage');if(el)el.textContent=message}
function draftRender(){const d=draftRead(),jc=normalizeJobCard(d.jobCard),j=job(jc)||{},vehicle=[j.make||j.vehicle||'',j.model||'',j.year||''].filter(Boolean).join(' '),box=document.getElementById('v2SpDraftDetails'),body=document.getElementById('v2SpDraftRows'),button=document.getElementById('v2SpDraftCreate');if(!box||!body)return;box.innerHTML=jc?'<div class="notice" style="margin:10px 0;background:#eef5fc;color:#173651"><b>Selected Job Card '+esc(jc)+'</b><br>'+esc(vehicle||'Vehicle details will be confirmed by server on creation')+'<br>Reg '+esc(j.reg||j.registration||'—')+' · Date '+esc(new Date().toLocaleDateString())+'</div><label>Insurance company / customer<input id="v2SpDraftCustomer" value="'+esc(d.customer||j.insuranceCompany||j.customerName||'')+'" placeholder="Type if not available on Job Card" oninput="zukaitV2.sparePartsMain.draftCustomer(this.value)"></label>':'<p class="muted">Find a Job Card to begin.</p>';body.innerHTML=(d.items||[]).map((x,i)=>'<tr><td>'+(i+1)+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.qty)+'</td><td><button type="button" onclick="zukaitV2.sparePartsMain.draftEdit('+i+')" style="'+spareBtn('edit')+';min-height:38px">Edit</button> <button type="button" onclick="zukaitV2.sparePartsMain.draftDelete('+i+')" style="'+spareBtn('danger')+';min-height:38px">Delete</button></td></tr>').join('')||'<tr><td colspan="4">No parts added yet.</td></tr>';button.textContent='Create Parts List · '+(d.items||[]).length+' item(s)';button.disabled=!jc||!(d.items||[]).length;const count=document.getElementById('v2SpDraftCount');if(count)count.textContent=(d.items||[]).length+' items · draft saved';}
function draftFind(){const jc=normalizeJobCard(document.getElementById('v2SpareJob')?.value),d=draftRead();if(!jc)return draftMessage('Enter a Job Card number.');if(d.jobCard&&d.jobCard!==jc&&(d.items||[]).length)return draftMessage('Finish or clear the current draft before switching Job Cards.');d.jobCard=jc;d.items=d.items||[];draftSave(d);draftRender();draftMessage(job(jc)?'Job Card selected.':'Job Card will be checked on the server when you create the list.')}
function draftCustomer(value){const d=draftRead();d.customer=String(value||'').trim();draftSave(d)}
function draftAdd(){const d=draftRead(),name=String(document.getElementById('v2SpDraftName')?.value||'').trim(),qty=validQty(document.getElementById('v2SpDraftQty')?.value);if(!d.jobCard)return draftMessage('Find a Job Card first.');if(!name||qty==null)return draftMessage('Enter a part name and a valid quantity.');d.items=d.items||[];const previous=d.items.find((x,i)=>i!==d.editIndex&&partKey(x.name)===partKey(name));if(previous){draftMessage('Part already listed. Edit its quantity below.');return}if(Number.isInteger(d.editIndex)&&d.items[d.editIndex]){d.items[d.editIndex]={name,qty};delete d.editIndex}else d.items.push({name,qty});draftSave(d);document.getElementById('v2SpDraftName').value='';document.getElementById('v2SpDraftQty').value='1';draftRender();document.getElementById('v2SpDraftName')?.focus();draftMessage('Part added.')}
function draftEdit(i){const d=draftRead(),x=d.items?.[i];if(!x)return;document.getElementById('v2SpDraftName').value=x.name;document.getElementById('v2SpDraftQty').value=x.qty;d.editIndex=i;draftSave(d);draftMessage('Update the part above and press Add.')}
function draftDelete(i){const d=draftRead();if(!d.items?.[i])return;const removed=d.items.splice(i,1)[0];delete d.editIndex;draftSave(d);draftRender();draftMessage('Removed '+removed.name+'.');}
function managerCreatePanel(){if(!canManage())return;ensureSparePartsUiStyle();const d=draftRead();window.openModal(withNav('<div class="v2-sp-manager-create" style="background:#f5f9fd;color:#173651;padding:15px;border-radius:17px"><h3 style="margin:0 0 5px">Create Parts List</h3><p class="muted">Find JC → Add parts → Send to Purchaser</p><div class="v2-sp-search"><input id="v2SpareJob" value="'+esc(d.jobCard||'')+'" placeholder="Job Card number" aria-label="Find Job Card"><button type="button" onclick="zukaitV2.sparePartsMain.draftFind()" style="'+spareBtn('primary')+'">Find Job Card</button></div><div id="v2SpDraftDetails"></div><h4>Add part</h4><div class="v2-sp-addrow"><input id="v2SpDraftName" placeholder="Item" aria-label="Item"><input id="v2SpDraftQty" type="number" min="1" value="1" aria-label="Quantity"><button type="button" onclick="zukaitV2.sparePartsMain.draftAdd()" style="'+spareBtn('primary')+'">＋ Add</button></div><h4>Parts to send <small id="v2SpDraftCount"></small></h4><div style="overflow-x:auto"><table style="width:100%;text-align:left"><thead><tr><th>No.</th><th>Parts</th><th>Qty</th><th>Actions</th></tr></thead><tbody id="v2SpDraftRows"></tbody></table></div><button id="v2SpDraftCreate" type="button" onclick="zukaitV2.sparePartsMain.createFromUI()" style="'+spareBtn('success')+';width:100%;margin-top:14px">Create Parts List</button><p id="v2SpDraftMessage" role="status" aria-live="polite"></p></div>','zukaitV2.sparePartsMain.open()'));markSparePartsModal();draftRender()}
function partFullyArrived(item){return !!item?.arrivalAccepted}
function managerListMatches(r,bucket){const items=r.items||[],statuses=items.map(i=>String(i.status||'LISTED'));if(bucket==='ALL')return true;if(bucket==='NEW')return statuses.some(s=>['LISTED','ENQUIRY','QUOTED'].includes(s));if(bucket==='WAITING')return items.length>0&&!items.every(partFullyArrived);if(bucket==='ATTENTION')return items.some(i=>['RETURNED','UNAVAILABLE'].includes(i.status)||i.cashSettlementRequired);if(bucket==='PURCHASE_COMPLETED')return items.length>0&&items.every(partFullyArrived);if(bucket==='DELIVERED_PENDING')return r.vehicleDeliveredPartsPending===true||r.deliveryPartsPending===true||r.deliveredPendingParts===true||String(r.status||'').toUpperCase()==='DELIVERED_PENDING';return statuses.some(s=>bucket==='RECEIVED'?['RECEIVED','SUPERVISOR_VERIFIED'].includes(s):s===bucket)}
async function renderSupervisorDashboard(){ensureSparePartsUiStyle();const rows=await hydrateAuthoritativeLists(),attention=attentionForRole(rows,'Supervisor').length,sum=managerDashboardSummary(rows),cards=[['📝','Create Parts List','New PL','CREATE','primary'],['🆕','New Parts List',rows.filter(r=>managerListMatches(r,'NEW')).length,'NEW','info'],['📋','Parts List',rows.length,'ALL','neutral'],['⏳','Parts Waiting',sum.waiting,'WAITING','wait'],['✅','Purchase Completed',sum.purchaseCompleted,'PURCHASE_COMPLETED','success'],['🚗','Delivered Vehicle – Pending Parts',sum.deliveredPending,'DELIVERED_PENDING','danger']];const recent=rows.slice().sort((a,b)=>new Date(b.updatedAt||b.createdAt||0)-new Date(a.updatedAt||a.createdAt||0)).slice(0,6).map(r=>'<button class="v2-sp-recent" onclick="zukaitV2.sparePartsMain.openList(\''+esc(r.listNo)+'\')"><b>'+esc(r.listNo)+'</b> · JC '+esc(r.jobCard)+'<small style="display:block">'+esc([r.vehicle,r.model,r.year,r.registration].filter(Boolean).join(' · '))+' · '+((r.items||[]).length)+' part(s)</small></button>').join('')||'<p class="muted">No recent Parts Lists.</p>';const operational=cards.map(x=>'<button class="v2-sp-tile" style="'+dashboardTile(x[4])+'" onclick="'+(x[3]==='CREATE'?'zukaitV2.sparePartsMain.managerCreatePanel()':"zukaitV2.sparePartsMain.managerBucket('"+x[3]+"')")+'"><span style="font-size:22px">'+x[0]+'</span><b style="display:block;margin-top:5px">'+x[1]+'</b><strong style="font-size:19px">'+x[2]+'</strong></button>').join('');window.openModal(withNav('<div class="v2-sp-manager v2-sp-dashboard"><div><h3 style="margin:0">🚗⚙️ Spare Parts</h3><small>Supervisor · Operational Parts Control</small></div><button class="v2-sp-attention" style="'+dashboardTile(attention?'wait':'neutral')+'" onclick="zukaitV2.sparePartsMain.openAttention()">⚠ Parts Attention <strong style="float:right">'+attention+'</strong></button><div class="v2-sp-search" style="margin-top:12px"><input id="v2SpManagerSearch" placeholder="Search JC / PL / registration / vehicle / part"><button class="blue" onclick="zukaitV2.sparePartsMain.managerSearch()">Search</button></div><div class="v2-sp-grid2" style="margin-top:12px">'+operational+'</div><h4 style="margin:14px 0 6px">Recent Activity</h4>'+recent+'</div>'));markSparePartsModal()}
async function renderManagerDashboard(){ensureSparePartsUiStyle();const rows=await hydrateAuthoritativeLists(),sum=managerDashboardSummary(rows),cards=[['📝','Create Parts List','New PL','CREATE'],['🆕','New Parts List',rows.filter(r=>managerListMatches(r,'NEW')).length,'NEW'],['📋','Parts List',rows.length,'ALL'],['⏳','Parts Waiting',sum.waiting,'WAITING'],['✅','Purchase Completed',sum.purchaseCompleted,'PURCHASE_COMPLETED'],['🚗','Delivered Vehicle – Pending Parts',sum.deliveredPending,'DELIVERED_PENDING']];const recent=rows.slice().sort((a,b)=>new Date(b.updatedAt||b.createdAt||0)-new Date(a.updatedAt||a.createdAt||0)).slice(0,6).map(r=>'<button class="v2-sp-recent" onclick="zukaitV2.sparePartsMain.openList(\''+esc(r.listNo)+'\')"><b>'+esc(r.listNo)+'</b> · JC '+esc(r.jobCard)+'<small style="display:block">'+esc([r.vehicle,r.model,r.year,r.registration].filter(Boolean).join(' · '))+' · '+((r.items||[]).length)+' part(s)</small></button>').join('')||'<p class="muted">No recent Parts Lists.</p>';const summary='<div class="v2-sp-grid2 v2-sp-summary" style="margin-top:12px"><div class="notice"><b>⚠ Parts Attention</b><div class="stat">'+sum.attention+'</div></div><div class="notice"><b>⏳ Parts Waiting</b><div class="stat">'+sum.waiting+'</div></div><div class="notice"><b>🚗 Delivered – Pending</b><div class="stat">'+sum.deliveredPending+'</div></div><div class="notice"><b>💰 Month Purchase</b><div class="stat">'+sum.monthSpend.toFixed(3)+' OMR</div></div></div>';const operational=cards.map(x=>{const kind=x[3]==='CREATE'?'primary':x[3]==='WAITING'?'wait':x[3]==='PURCHASE_COMPLETED'?'success':x[3]==='DELIVERED_PENDING'?'danger':x[3]==='NEW'?'info':'neutral';return '<button class="v2-sp-tile" style="'+dashboardTile(kind)+'" onclick="'+(x[3]==='CREATE'?'zukaitV2.sparePartsMain.managerCreatePanel()':"zukaitV2.sparePartsMain.managerBucket('"+x[3]+"')")+'"><span style="font-size:22px">'+x[0]+'</span><b style="display:block;margin-top:5px">'+x[1]+'</b><strong style="font-size:19px">'+x[2]+'</strong></button>'}).join('');window.openModal(withNav('<div class="v2-sp-manager v2-sp-dashboard"><div><h3 style="margin:0">🚗⚙️ Spare Parts</h3><small>Manager · Supervisor operational view + management controls</small></div>'+summary+'<div class="v2-sp-search" style="margin-top:12px"><input id="v2SpManagerSearch" placeholder="Search JC / PL / registration / vehicle / part"><button class="blue" onclick="zukaitV2.sparePartsMain.managerSearch()">Search</button></div><h4 style="margin:14px 0 7px">Operations</h4><div class="v2-sp-grid2">'+operational+'</div><h4 style="margin:14px 0 7px">Manager Controls</h4><div class="v2-sp-grid2"><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.openManagerReport()">📊 Reports</button><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.managerBucket(\'ALL\')">✏️ View / Edit</button><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.managerBucket(\'ATTENTION\')">⚠ Attention '+sum.attention+'</button><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.managerBucket(\'ALL\')">📚 History / Audit</button></div><h4 style="margin:14px 0 6px">Recent Activity</h4>'+recent+'</div>'))}
let activePartsBucket='ALL';
function partsBucketRows(){const q=String(document.getElementById('v2SpBucketSearch')?.value||'').trim().toLowerCase(),host=document.getElementById('v2SpBucketRows');if(!host)return;const rows=read().filter(r=>managerListMatches(r,activePartsBucket)).filter(r=>!q||[r.listNo,r.jobCard,r.registration,r.vehicle,r.model,r.year].some(x=>String(x||'').toLowerCase().includes(q)));host.innerHTML=rows.slice(0,200).map(r=>'<button type="button" data-list="'+esc(r.listNo)+'" onclick="zukaitV2.sparePartsMain.bucketOpen(this)" style="width:100%;text-align:left;display:block;margin:6px 0;padding:12px;background:#fff;color:#173651;border:1px solid #d7e4ef;border-radius:11px"><strong>'+esc(r.listNo)+'</strong> · '+esc(String(r.createdAt||'').slice(0,10))+' · JC '+esc(r.jobCard)+'<small style="display:block"> '+esc([r.vehicle,r.model,r.year].filter(Boolean).join(' '))+' · Reg '+esc(r.registration||'—')+' · '+(r.items||[]).length+' parts</small></button>').join('')||'<p class="muted">No matching Parts Lists.</p>'}
function bucketOpen(button){const no=button?.dataset?.list;if(no)openList(no)}
async function managerBucket(status){activePartsBucket=status;await hydrateAuthoritativeLists();const title=status==='WAITING'?'Parts Waiting':status==='PURCHASE_COMPLETED'?'Purchase Completed':'Parts Lists';window.openModal(withNav('<h3>'+title+'</h3><label>Search by JC / PL / registration<input id="v2SpBucketSearch" type="search" placeholder="Job Card, PL number or registration" oninput="zukaitV2.sparePartsMain.partsBucketRows()"></label><div id="v2SpBucketRows"></div>','zukaitV2.sparePartsMain.open()'));markSparePartsModal();partsBucketRows()}
function managerSearch(){const q=String(document.getElementById('v2SpManagerSearch')?.value||'').trim().toLowerCase();if(!q)return managerBucket('ALL');const rows=read().filter(r=>[r.listNo,r.jobCard,r.vehicle,r.registration].some(v=>String(v||'').toLowerCase().includes(q))||(r.items||[]).some(i=>[i.name,i.partNo,i.supplier].some(v=>String(v||'').toLowerCase().includes(q))));if(rows.length===1)return openList(rows[0].listNo);const body=rows.length?rows.map(r=>'<button class="secondary" style="width:100%;margin:5px 0;text-align:left" onclick="zukaitV2.sparePartsMain.openList(\''+esc(r.listNo)+'\')"><b>'+esc(r.listNo)+'</b> · JC '+esc(r.jobCard)+'</button>').join(''):'<p class="muted">No matching Parts Lists.</p>';window.openModal(withNav('<h3>Search Results</h3>'+body))}
async function render(){if(!canOpen()){alert('Spare Parts access unavailable.');return}if(role()==='Manager')return renderManagerDashboard();if(role()==='Supervisor')return renderSupervisorDashboard();if(role()==='Purchaser')return renderPurchaserDashboard();const allRows=await hydrateAuthoritativeLists(),rows=roleScopedLists(allRows),roleAttention=attentionForRole(rows).length;const body=rows.length?rows.slice(0,100).map(r=>'<button class="secondary" style="width:100%;margin:5px 0;text-align:left" onclick="zukaitV2.sparePartsMain.openList(\''+esc(r.listNo)+'\')"><b>'+esc(r.listNo)+'</b> · JC '+esc(r.jobCard)+' · '+r.items.length+' part(s)</button>').join(''):'<p class="muted">No Parts Lists yet.</p>';const createBox=denterView()?'':'<p class="muted">Create a Parts List from an existing Job Card. List numbers are automatic.</p><div class="v2-sp-search"><input id="v2SpareJob" placeholder="Job Card number"><button class="blue" onclick="zukaitV2.sparePartsMain.createFromUI()">Create Parts List</button></div><hr>';const report=role()==='Manager'?'<button class="blue" style="width:100%;margin:8px 0" onclick="zukaitV2.sparePartsMain.openManagerReport()">📊 Spare Parts Report</button>':'';const html='<h3>🔩 Spare Parts</h3><button style="'+spareBtn(roleAttention?'wait':'neutral')+';width:100%;text-align:left;margin-bottom:10px" onclick="zukaitV2.sparePartsMain.openAttention()">⚠ Needs your attention <strong style="float:right">'+roleAttention+'</strong></button>'+report+createBox+body;if(typeof window.openModal==='function')window.openModal(withNav(html))}
function openAttention(){const rows=roleScopedLists(read()),matches=attentionForRole(rows),seen=new Set(),cards=[];for(const x of matches){const key=String(x.list?.listNo||'');if(!key||seen.has(key))continue;seen.add(key);const count=matches.filter(y=>String(y.list?.listNo||'')===key).length;cards.push('<button class="secondary" style="width:100%;margin:5px 0;text-align:left" onclick="zukaitV2.sparePartsMain.openList(\''+esc(key)+'\')"><b>'+esc(key)+'</b> · JC '+esc(x.list?.jobCard||'')+'<small style="display:block">'+count+' item(s) need your action</small></button>')}window.openModal(withNav('<h3>⚠ Needs your attention</h3>'+(cards.join('')||'<p class="muted">Nothing needs your attention now.</p>'),'zukaitV2.sparePartsMain.open()'))}
async function createFromUI(){if(!canManage())return alert('FORBIDDEN');const draft=draftRead(),jobCard=normalizeJobCard(draft.jobCard),items=draft.items||[];if(!jobCard||!items.length)return draftMessage('Find a Job Card and add at least one part.');if(!navigator.onLine||!window.zukaitCloud?.allocateSparePartList)return draftMessage('Connect to the server before creating the Parts List. Your draft is saved.');const button=document.getElementById('v2SpDraftCreate');if(button)button.disabled=true;draftMessage('Creating Parts List…');try{const allocation=await window.zukaitCloud.allocateSparePartList(jobCard),rows=read(),j=job(jobCard)||{},u=currentUser()||{};let list=rows.find(x=>x.listNo===allocation.list_no);if(!list){list={listNo:allocation.list_no,jobCard,vehicle:allocation.vehicle||j.vehicle||j.make||'',model:allocation.model||j.model||'',year:allocation.year||j.year||'',registration:allocation.registration||j.reg||j.registration||'',customer:draft.customer||j.insuranceCompany||j.customerName||'',status:allocation.status||'OPEN',items:[],createdAt:allocation.created_at||new Date().toISOString(),createdBy:allocation.created_by||u.id||null,createdByRole:u.role||null,serverAllocated:true};rows.unshift(list);write(rows)}const created=await syncList(list);if(!created.ok&&!created.queued)throw Error('List sync failed: '+created.reason);for(const part of items){if(list.items.some(x=>partKey(x.name)===partKey(part.name)))continue;const added=addItem(list.listNo,part);if(!added.ok)throw Error('Part '+part.name+': '+added.reason);list=added.list;const item=list.items[list.items.length-1];const synced=await commitEvent({eventId:'spare-item-'+item.id,entityId:item.id,actorId:u.id||null,type:'SPARE_PART_LISTED',serverRevision:1,payload:{partId:item.id,listNo:list.listNo,jobCard,name:item.name,partNo:item.partNo,qty:item.qty}});if(!synced.ok&&!synced.queued){list.items=list.items.filter(x=>x.id!==item.id);write(read().map(x=>x.listNo===list.listNo?list:x));throw Error('Part sync failed: '+synced.reason)}}localStorage.removeItem(DRAFT_KEY);openList(list.listNo)}catch(e){draftMessage(String(e?.code||e?.message||e)==='job_card_not_found'?'Job Card not found on server. Check its number and sync the Job Card. Your draft is saved.':'Could not finish: '+String(e?.code||e?.message||e)+'. Your draft is saved.');if(button)button.disabled=false}}
function partsListWhatsAppText(r){const vehicle=[r.vehicle,r.model,r.year].map(v=>String(v||'').trim()).filter(Boolean).reduce((a,v)=>a.some(x=>x.toLowerCase().includes(v.toLowerCase()))?a:[...a,v],[]).join(' ').replace(/\s+/g,' ').trim();const lines=[(vehicle||'Vehicle')+'.'];(r.items||[]).forEach((item,index)=>{const qty=Number(item.qty);lines.push((index+1)+'. '+String(item.name||'Part').trim()+(Number.isFinite(qty)&&qty>1?' '+qty:''))});return lines.join('\n')}
function partsListText(r){const lines=['ZUKAIT INTERNATIONAL LLC','SPARE PARTS LIST '+r.listNo,'JC '+r.jobCard,[r.vehicle,r.model,r.year,r.registration].filter(Boolean).join(' · '),''];(r.items||[]).forEach((x,i)=>lines.push((i+1)+'. '+x.name+(x.partNo?' · '+x.partNo:'')+' · Qty '+x.qty+' · '+(x.status||'LISTED')+(x.supplier?' · '+x.supplier:'')+(reportAmount(x)?' · '+reportAmount(x).toFixed(3)+' OMR':'')));return lines.join('\n')}
function printPartsList(no){if(!['Manager','Supervisor','Purchaser'].includes(role()))return;const r=read().find(x=>x.listNo===no);if(!r)return;const vehicle=[r.vehicle,r.model,r.year].map(v=>String(v||'').trim()).filter(Boolean).reduce((a,v)=>a.some(x=>x.toLowerCase().includes(v.toLowerCase()))?a:[...a,v],[]).join(' ');const rows=(r.items||[]).map((x,i)=>{const price=[x.finalPrice,x.purchaseAmount,x.quoteAmount,x.billAmount,x.price].find(v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v)));const qty=Number(x.qty);const name=String(x.name||'Part')+(Number.isFinite(qty)&&qty>1?' '+qty:'');return '<tr><td>'+(i+1)+'</td><td>'+esc(name)+'</td><td>'+(price===undefined?'':esc(Number(price).toFixed(3)))+'</td></tr>'}).join('');const w=window.open('','_blank');if(!w){alert('Print window blocked.');return}w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Parts List '+esc(no)+'</title><style>@page{size:A4;margin:16mm}body{font-family:Arial,sans-serif;color:#111;margin:0}h1{font-size:20px;margin:0 0 12px}p{font-size:13px;margin:5px 0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #555;padding:8px;text-align:left;vertical-align:top}th:first-child,td:first-child{width:52px}th:last-child,td:last-child{width:110px;text-align:right}thead{display:table-header-group}</style></head><body><h1>SN '+esc(r.listNo)+'</h1><p><b>Job number:</b> '+esc(r.jobCard)+'</p><p><b>Make and model:</b> '+esc(vehicle||'—')+'</p><p><b>Reg number:</b> '+esc(r.registration||'—')+'</p><table><thead><tr><th>No.</th><th>Item</th><th>Price</th></tr></thead><tbody>'+rows+'</tbody></table></body></html>');w.document.close();w.focus();w.print()}

async function sharePartsList(no){if(role()!=='Manager')return;const r=read().find(x=>x.listNo===no);if(!r)return;const text=partsListText(r);try{if(navigator.share){await navigator.share({title:'Spare Parts '+r.listNo,text});return}}catch(e){if(e?.name==='AbortError')return}try{await navigator.clipboard.writeText(text);alert('Parts List copied. You can share it from this device.')}catch(_){alert('Share is unavailable on this device. Use Print / PDF.')}}
function whatsAppPartsList(no){if(!['Manager','Purchaser'].includes(role()))return;const r=read().find(x=>x.listNo===no);if(!r)return;const url='https://wa.me/?text='+encodeURIComponent(partsListWhatsAppText(r));try{const w=window.open(url,'_blank');if(w)return}catch(_){}window.location.href=url}
function openManagerEditItem(listNo,itemId){if(role()!=='Manager')return;ensureSparePartsUiStyle();const list=read().find(x=>x.listNo===listNo),item=list?.items?.find(x=>x.id===itemId);if(!item)return;const amount=reportAmount(item);window.openModal(withNav('<h3>✏️ Edit Part</h3><p><b>'+esc(listNo)+'</b> · JC '+esc(list.jobCard)+'</p><label>Part Name<input id="v2SpEditName" value="'+esc(item.name||'')+'"></label><label>Part No.<input id="v2SpEditPartNo" value="'+esc(item.partNo||'')+'"></label><label>Quantity<input id="v2SpEditQty" type="number" min="1" value="'+Number(item.qty||1)+'"></label><label>Supplier<input id="v2SpEditSupplier" value="'+esc(item.supplier||'')+'"></label><label>Recorded Amount OMR<input id="v2SpEditAmount" type="number" min="0" step="0.001" value="'+(amount||'')+'"></label><button class="big-action" onclick="zukaitV2.sparePartsMain.saveManagerItemEdit(\''+esc(listNo)+'\',\''+esc(itemId)+'\')" style="'+spareBtn('success')+'">SAVE CHANGES</button>','zukaitV2.sparePartsMain.openList(\''+esc(listNo)+'\')'))}
async function saveManagerItemEdit(listNo,itemId){if(role()!=='Manager')return;const rows=read(),list=rows.find(x=>x.listNo===listNo),item=list?.items?.find(x=>x.id===itemId);if(!item)return;const name=String(document.getElementById('v2SpEditName')?.value||'').trim(),partNo=String(document.getElementById('v2SpEditPartNo')?.value||'').trim().toUpperCase(),qty=validQty(document.getElementById('v2SpEditQty')?.value),supplier=String(document.getElementById('v2SpEditSupplier')?.value||'').trim(),amountRaw=document.getElementById('v2SpEditAmount')?.value,amount=amountRaw===''?null:validMoney(amountRaw);if(!name)return alert('Part name is required.');if(qty==null)return alert('Enter a valid quantity.');if(amountRaw!==''&&amount==null)return alert('Enter a valid amount.');const before={name:item.name,partNo:item.partNo,qty:item.qty,supplier:item.supplier,purchaseAmount:item.purchaseAmount,editRevision:item.editRevision};const editRevision=Number(item.editRevision||0)+1;Object.assign(item,{name,partNo,qty,supplier,editRevision,updatedAt:new Date().toISOString(),updatedBy:currentUser()?.id||null});if(amount==null)delete item.purchaseAmount;else item.purchaseAmount=amount;list.updatedAt=item.updatedAt;write(rows);const synced=await commitEvent({eventId:'spare-edit-'+itemId+'-'+editRevision,entityId:itemId,actorId:currentUser()?.id||null,type:'SPARE_PART_ITEM_EDITED',serverRevision:editRevision,payload:{partId:itemId,listNo,jobCard:list.jobCard,before,after:{name,partNo,qty,supplier,purchaseAmount:amount}}});if(!synced.ok&&!synced.queued){Object.assign(item,before);write(rows);alert('Unable to save change: '+synced.reason);return}openList(listNo)}
function supervisorPriceClick(button){if(button?.dataset?.list&&button?.dataset?.item)saveSupervisorFinalPrice(button.dataset.list,button.dataset.item)}
async function saveSupervisorFinalPrice(listNo,itemId){if(!['Supervisor','Manager'].includes(role()))return;const list=read().find(x=>x.listNo===listNo),item=list?.items?.find(x=>x.id===itemId);if(!item||!['SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED'].includes(item.status))return alert('Verify the arrived part first.');const raw=window.prompt('Final price for '+item.name+' (OMR)',item.finalPrice==null?'':String(item.finalPrice));if(raw===null)return;const amount=validMoney(raw);if(amount==null)return alert('Enter a valid final price in OMR.');if(!window.confirm('Save final price '+amount.toFixed(3)+' OMR for '+item.name+'?'))return;const revision=Number(item.finalPriceRevision||0)+1,previous=item.finalPrice;item.finalPrice=amount;item.finalPriceRevision=revision;write(read().map(r=>r.listNo===listNo?list:r));const result=await commitEvent({eventId:'spare-final-price-'+itemId+'-'+revision,entityId:itemId,actorId:currentUser()?.id||null,type:'SPARE_PART_FINAL_PRICE_RECORDED',serverRevision:revision,payload:{partId:itemId,listNo,jobCard:list.jobCard,finalPrice:amount}});if(!result.ok&&!result.queued){if(previous==null)delete item.finalPrice;else item.finalPrice=previous;item.finalPriceRevision=revision-1;write(read().map(r=>r.listNo===listNo?list:r));alert('Could not save final price: '+result.reason);return}openList(listNo)}
function purchaserActions(listNo,item){if(role()!=='Purchaser')return '';const action=nextActionFor(item,'Purchaser'),pending=pendingTransition(item),conflict=!!item.syncConflict;return '<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap"><button onclick="zukaitV2.sparePartsMain.openPurchaserItem(\''+esc(listNo)+'\',\''+esc(item.id)+'\')" style="'+spareBtn('primary')+'">🛒 Purchasing Details</button>'+(conflict?'<button disabled style="'+spareBtn('danger')+';opacity:.85">⚠ Sync conflict</button>':pending?'<button disabled style="'+spareBtn('neutral')+';opacity:.75">⟳ Pending sync</button>':action?'<button style="'+spareBtn(action[2])+'" onclick="zukaitV2.sparePartsMain.purchaserAdvance(\''+esc(listNo)+'\',\''+esc(item.id)+'\',\''+action[1]+'\')">'+esc(action[0])+'</button>':'')+'</div>'}
function roleActionButton(listNo,item){if(item?.syncConflict)return '<button disabled style="'+spareBtn('danger')+';margin-top:6px;opacity:.85">⚠ Sync conflict</button>';if(pendingTransition(item))return '<button disabled style="'+spareBtn('neutral')+';margin-top:6px;opacity:.75">⟳ Pending sync</button>';const r=role(),action=nextActionFor(item,r);if(!action)return '';if(r==='Denter')return '<button style="'+spareBtn('wait')+';margin-top:6px" onclick="zukaitV2.sparePartsMain.notifySupervisor(\''+esc(listNo)+'\',\''+esc(item.id)+'\')">🔔 '+esc(action[0])+'</button>';if(r==='Purchaser')return '';return '<button style="'+spareBtn(action[2])+';margin-top:6px" onclick="zukaitV2.sparePartsMain.quickAdvance(\''+esc(listNo)+'\',\''+esc(item.id)+'\',\''+esc(action[1])+'\')">→ '+esc(action[0])+'</button>'}
function openPurchaserItem(listNo,itemId){if(role()!=='Purchaser')return;ensureSparePartsUiStyle();const list=read().find(x=>x.listNo===listNo),item=list?.items?.find(x=>x.id===itemId);if(!item)return;window.openModal(withNav('<h3>🛒 Purchasing Details</h3><p><b>'+esc(listNo)+'</b> · JC '+esc(list.jobCard)+'</p><p>'+esc(item.name)+' · Qty '+Number(item.qty||0)+' · '+esc(item.status)+'</p><label>Supplier<input id="v2SpPurchaseSupplier" value="'+esc(item.supplier||'')+'"></label><label>Quotation OMR<input id="v2SpPurchaseQuote" type="number" min="0" step="0.001" value="'+(item.quoteAmount??'')+'"></label><label>Purchase Amount OMR<input id="v2SpPurchaseAmount" type="number" min="0" step="0.001" value="'+(item.purchaseAmount??'')+'"></label><button class="big-action" onclick="zukaitV2.sparePartsMain.savePurchaserItem(\''+esc(listNo)+'\',\''+esc(itemId)+'\')" style="'+spareBtn('success')+'">SAVE PURCHASING DETAILS</button>','zukaitV2.sparePartsMain.openList(\''+esc(listNo)+'\')'))}
async function savePurchaserItem(listNo,itemId){if(role()!=='Purchaser')return;const rowsBefore=read(),listBefore=rowsBefore.find(x=>x.listNo===listNo),before=listBefore?.items?.find(x=>x.id===itemId)?Object.assign({},listBefore.items.find(x=>x.id===itemId)):null;const patch={supplier:document.getElementById('v2SpPurchaseSupplier')?.value||'',quoteAmount:document.getElementById('v2SpPurchaseQuote')?.value||'',purchaseAmount:document.getElementById('v2SpPurchaseAmount')?.value||''},r=updateCommercial(listNo,itemId,patch);if(!r.ok)return alert(r.reason);const stored=read(),list=stored.find(x=>x.listNo===listNo),storedItem=list?.items?.find(x=>x.id===itemId),rev=Number(before?.commercialRevision||0)+1;if(storedItem)storedItem.commercialRevision=rev;write(stored);const synced=await commitEvent({eventId:'spare-commercial-'+itemId+'-'+rev,entityId:itemId,actorId:currentUser()?.id||null,type:'SPARE_PART_COMMERCIAL_UPDATED',serverRevision:rev,payload:{partId:itemId,listNo,jobCard:list?.jobCard,supplier:r.item.supplier||'',quoteAmount:r.item.quoteAmount??null,purchaseAmount:r.item.purchaseAmount??null}});if(!synced.ok&&!synced.queued){const rows=read(),l=rows.find(x=>x.listNo===listNo),i=l?.items?.find(x=>x.id===itemId);if(i&&before)Object.assign(i,before);write(rows);return alert('Unable to sync purchasing details: '+synced.reason)}openList(listNo)}
async function purchaserAdvance(listNo,itemId,to){if(role()!=='Purchaser')return;if(to==='ACCEPTED')return acceptArrival(listNo,itemId);const item=read().find(x=>x.listNo===listNo)?.items?.find(x=>x.id===itemId);if(!item||item.syncConflict||pendingTransition(item))return;if(!window.confirm('Change '+item.name+' to '+String(to||'').replace(/_/g,' ')+'?'))return;const r=await transitionItem(listNo,itemId,to);if(!r.ok)return alert(r.reason);openList(listNo)}
function purchaserListTable(list){const rows=(list.items||[]).map((item,index)=>{const state=String(item.status||'LISTED'),arrived=partFullyArrived(item),waiting=state==='ENQUIRY'||state==='QUOTED'||state==='ORDERED'||arrived,ordered=state==='ORDERED'||arrived,blocked=!!item.syncConflict||pendingTransition(item),returned=state==='RETURNED';const stage=(title,complete,enabled,to,color)=>'<button type="button" data-list="'+esc(list.listNo)+'" data-item="'+esc(item.id)+'" data-to="'+to+'" onclick="zukaitV2.sparePartsMain.purchaserStatusClick(this)" '+(complete||!enabled||blocked?'disabled':'')+' style="'+spareBtn(color)+';opacity:'+(complete||enabled?1:.4)+';min-width:75px" aria-label="'+esc(title)+' '+esc(item.name)+'">'+(complete?'✓ ':'')+title+'</button>';return '<tr style="border-bottom:1px solid #dbe5f0;background:'+(arrived?'#e6f6ec':'#fff')+'"><td>'+(index+1)+'</td><td><b>'+esc(item.name)+'</b><small style="display:block">Qty '+esc(item.qty||1)+'</small></td><td><button type="button" data-list="'+esc(list.listNo)+'" data-item="'+esc(item.id)+'" onclick="zukaitV2.sparePartsMain.purchaserPriceClick(this)" style="'+spareBtn('edit')+'">'+(item.quoteAmount==null?'Enter price':esc(Number(item.quoteAmount).toFixed(3))+' OMR')+'</button></td><td>'+stage('Waiting',waiting,state==='LISTED','ENQUIRY','primary')+'</td><td>'+stage('Ordered',ordered,state==='QUOTED'||(state==='ENQUIRY'&&item.quoteAmount!=null),'ORDERED','wait')+'</td><td>'+stage(item.arrivalAccepted?'Arrived':['SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED'].includes(state)?'Confirm':'Arrived',arrived,state==='ORDERED'||['SUPERVISOR_VERIFIED','DENTER_CHECKED'].includes(state),['SUPERVISOR_VERIFIED','DENTER_CHECKED'].includes(state)?'ACCEPTED':'RECEIVED','success')+'</td><td>'+stage('Returned',returned,['ORDERED','RECEIVED'].includes(state),'RETURNED','danger')+'</td><td>'+(item.finalPrice==null?'—':esc(Number(item.finalPrice).toFixed(3))+' OMR')+'</td></tr>'}).join('');const vehicle=[list.vehicle,list.model,list.year].filter(Boolean).join(' ');return '<div class="v2-pl-detail"><div class="v2-pl-hero"><h3>📋 '+esc(list.listNo)+'</h3><p>'+esc(vehicle||'Vehicle')+' · JC '+esc(list.jobCard)+' · Reg '+esc(list.registration||'—')+'</p><small>'+esc(list.customer||'')+' · '+esc(String(list.createdAt||'').slice(0,10))+'</small></div><div style="overflow-x:auto;margin-top:14px"><table style="width:100%;min-width:780px;text-align:left;border-collapse:collapse"><thead><tr><th>No.</th><th>Part / Qty</th><th>Price</th><th>Waiting</th><th>Ordered</th><th>Arrived</th><th>Returned</th><th>Final price</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="v2-pl-tools"><button onclick="zukaitV2.sparePartsMain.printPartsListFromPurchaser()" style="'+spareBtn('primary')+'">Print / PDF</button><button onclick="zukaitV2.sparePartsMain.whatsAppPartsListFromPurchaser()" style="'+spareBtn('success')+'">WhatsApp text</button></div><p class="muted">Confirm each status change. All arrived parts turn green.</p></div>'}
let currentPurchaserListNo='';
async function acceptArrival(listNo,itemId){if(role()!=='Purchaser')return;if(!navigator.onLine)return alert('Connect to the server to confirm final arrival.');await hydrateAuthoritativeLists();const list=read().find(x=>x.listNo===listNo),item=list?.items?.find(x=>x.id===itemId);if(!item||item.arrivalAccepted||item.syncConflict||pendingTransition(item))return;if(!['SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED'].includes(String(item.status||'')))return alert('Wait for Supervisor verification before final arrival confirmation.');if(!window.confirm('Confirm '+item.name+' was checked and accepted?'))return;const eventId='spare-arrival-accepted-'+itemId,done=await commitEvent({eventId,entityId:itemId,actorId:currentUser()?.id||null,type:'SPARE_PART_ARRIVAL_ACCEPTED',serverRevision:1,payload:{partId:itemId,listNo,jobCard:list.jobCard}});if(!done.ok)return alert(done.queued?'Final confirmation is waiting for sync. The list will move after the server receives it.':'Could not confirm arrival: '+done.reason);item.arrivalAccepted=true;item.arrivalAcceptedAt=new Date().toISOString();write(read().map(r=>r.listNo===listNo?list:r));openList(listNo)}
function purchaserPriceClick(button){const listNo=button?.dataset?.list,itemId=button?.dataset?.item;if(!listNo||!itemId)return;openPurchaserItem(listNo,itemId)}
async function purchaserStatusClick(button){if(role()!=='Purchaser'||!button)return;const no=button.dataset.list,id=button.dataset.item,to=button.dataset.to,existing=read().find(x=>x.listNo===no)?.items?.find(x=>x.id===id);if(!existing||existing.syncConflict||pendingTransition(existing))return;const from=String(existing.status||'LISTED'),allowed=(to==='ENQUIRY'&&from==='LISTED')||(to==='ORDERED'&&(from==='QUOTED'||(from==='ENQUIRY'&&existing.quoteAmount!=null)))||(to==='RECEIVED'&&from==='ORDERED');if(to==='ACCEPTED')return acceptArrival(no,id);if(to==='RETURNED'&&!['ORDERED','RECEIVED'].includes(from))return alert('Only ordered or arrived parts can be returned.');if(!allowed&&to!=='RETURNED')return alert('Complete the previous purchasing stage first.');if(!window.confirm('Mark '+existing.name+' as '+({ENQUIRY:'Waiting',ORDERED:'Ordered',RECEIVED:'Arrived',RETURNED:'Returned'}[to])+'?'))return;const reason=to==='RETURNED'?String(window.prompt('Reason for returning '+existing.name+'?')||'').trim():'';if(to==='RETURNED'&&!reason)return;button.disabled=true;if(to==='ORDERED'&&from==='ENQUIRY'){const quote=await transitionItem(no,id,'QUOTED');if(!quote.ok){alert(quote.reason);openList(no);return}if(quote.sync?.queued){alert('Price update is pending sync. Mark Ordered after it finishes.');openList(no);return}}const r=await transitionItem(no,id,to,reason);if(!r.ok)alert(r.reason);openList(no)}
function printPartsListFromPurchaser(){if(currentPurchaserListNo)printPartsList(currentPurchaserListNo)}
function whatsAppPartsListFromPurchaser(){if(currentPurchaserListNo)whatsAppPartsList(currentPurchaserListNo)}
function ensurePartsListDetailStyle(){if(document.getElementById('v2PartsListDetailStyle'))return;const st=document.createElement('style');st.id='v2PartsListDetailStyle';st.textContent='.v2-pl-detail{background:linear-gradient(145deg,#f4faff,#edf5fb);border:1px solid #dce9f4;border-radius:19px;padding:14px;color:#1c3551}.v2-pl-hero{background:#fff;border:1px solid #d6e5f2;border-left:5px solid #2563eb;border-radius:16px;padding:15px;box-shadow:0 9px 24px #15385813}.v2-pl-hero-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.v2-pl-hero h3{font-size:22px;margin:0;color:#164777}.v2-pl-hero .v2-pl-count{background:#e7f2ff;color:#195a9a;border-radius:999px;padding:6px 10px;font-weight:800;font-size:12px}.v2-pl-vehicle{font-size:18px;font-weight:850;margin:10px 0 8px;color:#1e3d5e}.v2-pl-meta{display:flex;gap:7px;flex-wrap:wrap}.v2-pl-meta span{background:#eff5fb;border:1px solid #dae7f2;border-radius:9px;padding:6px 9px;color:#315473;font-weight:750;font-size:12px}.v2-pl-tools{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.v2-pl-tools button{margin:0;flex:1;min-width:130px}.v2-pl-section{display:flex;justify-content:space-between;align-items:center;margin:17px 0 8px}.v2-pl-section h4{font-size:16px;color:#254a70;margin:0}.v2-pl-item{background:#fff;border:1px solid #dce6ef;border-left:4px solid #7aa8d6;border-radius:14px;padding:12px;margin:8px 0;box-shadow:0 6px 16px #18314d0d}.v2-pl-item-main{display:flex;align-items:flex-start;justify-content:space-between;gap:9px}.v2-pl-item-title{display:flex;align-items:flex-start;gap:9px;min-width:0}.v2-pl-item-number{display:grid;place-items:center;min-width:29px;height:29px;background:#e8f2fd;color:#2462a0;border-radius:8px;font-weight:900}.v2-pl-item-title strong{font-size:15px;color:#173651;overflow-wrap:anywhere}.v2-pl-item-title small{display:block;color:#627a90;margin-top:3px}.v2-pl-status{display:inline-block;max-width:130px;text-align:center;padding:6px 8px;border-radius:9px;color:#fff;font-size:10px;font-weight:800;line-height:1.2}.v2-pl-facts{display:flex;gap:7px;flex-wrap:wrap;margin:9px 0 0 38px;color:#44627f;font-size:12px}.v2-pl-facts span{background:#f4f7fb;padding:5px 7px;border-radius:7px}.v2-pl-add{background:#fff;border:1px dashed #93b8db;border-radius:14px;padding:12px;margin-top:14px}.v2-pl-add h4{margin:0 0 8px;color:#254a70}@media(max-width:560px){.v2-pl-detail{padding:10px}.v2-pl-vehicle{font-size:16px}.v2-pl-tools button{min-width:0;flex-basis:calc(50% - 7px)}.v2-pl-item-main{align-items:flex-start}.v2-pl-status{max-width:90px}.v2-pl-facts{margin-left:0}}';document.head.appendChild(st)}
function openList(no){ensureSparePartsUiStyle();ensurePartsListDetailStyle();const r=read().find(x=>x.listNo===no);if(!r)return;if(role()==='Purchaser'){currentPurchaserListNo=no;window.openModal(withNav(purchaserListTable(r),'zukaitV2.sparePartsMain.open()'));markSparePartsModal();return}const isManager=role()==='Manager',isPurchaser=role()==='Purchaser',canPrint=['Manager','Supervisor','Purchaser'].includes(role());const vehicle=[r.vehicle,r.model,r.year].map(v=>String(v||'').trim()).filter(Boolean).reduce((a,v)=>a.some(x=>x.toLowerCase().includes(v.toLowerCase()))?a:[...a,v],[]).join(' ');const hero='<div class="v2-pl-hero"><div class="v2-pl-hero-top"><h3>📋 '+esc(r.listNo)+'</h3><span class="v2-pl-count">'+(r.items||[]).length+' part(s)</span></div><div class="v2-pl-vehicle">🚗 '+esc(vehicle||'Vehicle details pending')+'</div><div class="v2-pl-meta"><span>Job Card '+esc(r.jobCard)+'</span><span>Reg '+esc(r.registration||'—')+'</span></div></div>';const buttons=[];if(canPrint)buttons.push('<button type="button" style="'+spareBtn('primary')+'" onclick="zukaitV2.sparePartsMain.printPartsList(\''+esc(no)+'\')">🖨 Print / PDF</button>');if(isManager)buttons.push('<button type="button" style="'+spareBtn('info')+'" onclick="zukaitV2.sparePartsMain.sharePartsList(\''+esc(no)+'\')">↗ Share</button>');if(isManager||isPurchaser)buttons.push('<button type="button" style="'+spareBtn('success')+'" onclick="zukaitV2.sparePartsMain.whatsAppPartsList(\''+esc(no)+'\')">WhatsApp List</button>');const items=(r.items||[]).map((x,i)=>{const money=[x.purchaseAmount,x.quoteAmount,x.billAmount,x.price].find(v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v)));return '<article class="v2-pl-item"><div class="v2-pl-item-main"><div class="v2-pl-item-title"><span class="v2-pl-item-number">'+(i+1)+'</span><div><strong>'+esc(x.name)+'</strong>'+(x.partNo?'<small>Part No. '+esc(x.partNo)+'</small>':'')+'</div></div><span class="v2-pl-status" style="background:'+statusColour(x.status)+'">'+esc(String(x.status||'LISTED').replace(/_/g,' '))+'</span></div><div class="v2-pl-facts"><span>Qty <b>'+esc(x.qty||1)+'</b></span>'+((isManager||isPurchaser)&&x.supplier?'<span>Supplier <b>'+esc(x.supplier)+'</b></span>':'')+((isManager||isPurchaser)&&money!==undefined?'<span>Price <b>'+esc(Number(money).toFixed(3))+' OMR</b></span>':'')+'</div>'+(isManager?'<button onclick="zukaitV2.sparePartsMain.openManagerEditItem(\''+esc(no)+'\',\''+esc(x.id)+'\')" style="'+spareBtn('edit')+';margin-top:8px">Edit Part</button>':'')+purchaserActions(no,x)+roleActionButton(no,x)+(canManage()&&['SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED'].includes(String(x.status||''))?'<button type="button" data-list="'+esc(no)+'" data-item="'+esc(x.id)+'" onclick="zukaitV2.sparePartsMain.supervisorPriceClick(this)" style="'+spareBtn('success')+';margin-top:8px">Final price '+(x.finalPrice==null?'—':esc(Number(x.finalPrice).toFixed(3))+' OMR')+'</button>':'')+'</article>'}).join('')||'<div class="notice">No parts added yet.</div>';const add=canManage()?'<div class="v2-pl-add"><h4>＋ Add a part</h4><div class="v2-sp-addrow"><input id="v2PartName" placeholder="Part name"><input id="v2PartQty" type="number" min="1" value="1" aria-label="Quantity"><button onclick="zukaitV2.sparePartsMain.addFromUI(\''+esc(no)+'\')" style="'+spareBtn('primary')+'">Add Part</button></div></div>':'';window.openModal(withNav('<div class="v2-pl-detail">'+hero+'<div class="v2-pl-tools">'+buttons.join('')+'</div><div class="v2-pl-section"><h4>Parts</h4><span class="small">'+(r.items||[]).length+' listed</span></div>'+items+add+'</div>','zukaitV2.sparePartsMain.open()'));markSparePartsModal()}

async function quickAdvance(listNo,itemId,to){const r=await transitionItem(listNo,itemId,to);if(!r.ok)return alert(r.reason);openList(listNo)}
async function notifySupervisor(listNo,itemId){const list=read().find(x=>x.listNo===listNo),item=list?.items?.find(x=>x.id===itemId),u=currentUser()||{},wf=window.zukaitV2?.spareParts;if(!item||!wf)return {ok:false,reason:'PART_NOT_FOUND'};const n=wf.notifySupervisor(Object.assign({},item,{jobCard:list.jobCard}),{role:u.role,actorId:u.id});if(!n.ok)return n;const synced=await commitEvent({eventId:'spare-notice-'+itemId+'-'+String(item.status||'LISTED')+'-'+Number(item.revision||0),entityId:itemId,actorId:u.id||null,type:'SPARE_PART_DENTER_NOTICE',serverRevision:Number(item.revision||0),payload:{partId:itemId,listNo,jobCard:list.jobCard,targetRole:'Supervisor',status:item.status}});if(!synced.ok&&synced.reason!=='V2_TRANSPORT_UNAVAILABLE')return {ok:false,reason:'SYNC_FAILED',detail:synced.reason};alert('Supervisor notified.');return {ok:true,notification:n.notification,sync:synced}}
async function transitionItem(listNo,itemId,to,reason=''){const rows=read(),list=rows.find(x=>x.listNo===listNo);if(!list)return {ok:false,reason:'LIST_NOT_FOUND'};const idx=list.items.findIndex(x=>x.id===itemId);if(idx<0)return {ok:false,reason:'PART_NOT_FOUND'};if(list.items[idx]?.syncConflict)return {ok:false,reason:'SYNC_CONFLICT'};if(pendingTransition(list.items[idx]))return {ok:false,reason:'PENDING_SYNC'};const u=currentUser()||{},wf=window.zukaitV2?.spareParts;if(!wf)return {ok:false,reason:'WORKFLOW_UNAVAILABLE'};const previous=Object.assign({},list.items[idx]),nextRevision=Number(previous.revision||0)+1;const moved=wf.transition(Object.assign({},previous,{jobCard:list.jobCard}),to,{role:u.role,actorId:u.id,deviceId:window.zukaitDeviceId||null,reason});if(!moved.ok)return moved;moved.item.revision=nextRevision;list.items[idx]=moved.item;list.updatedAt=moved.item.updatedAt;write(rows);const eventId=['spare-status',itemId,String(previous.status||'LISTED'),to,nextRevision].join('-');const synced=await commitEvent({eventId,entityId:itemId,actorId:u.id||null,type:'SPARE_PART_STATUS_CHANGED',serverRevision:nextRevision,payload:{partId:itemId,listNo,jobCard:list.jobCard,from:previous.status,to,reason:reason||null,targetRole:to==='RECEIVED'?'Supervisor':null}});if(!synced.ok&&synced.reason!=='V2_TRANSPORT_UNAVAILABLE'){list.items[idx]=previous;write(rows);return {ok:false,reason:'SYNC_FAILED',detail:synced.reason}}if(synced.queued){list.items[idx].pendingSync=true;list.items[idx].pendingEventId=eventId;write(rows)}else{delete list.items[idx].pendingSync;delete list.items[idx].pendingEventId;write(rows)}return {ok:true,item:list.items[idx],sync:synced}}
async function addFromUI(no){if(!canManage())return alert('FORBIDDEN');const name=String(document.getElementById('v2PartName')?.value||'').trim(),qty=document.getElementById('v2PartQty')?.value;if(!name)return alert('PART_REQUIRED');if(navigator.onLine){await hydrateAuthoritativeLists();const fresh=read().find(x=>x.listNo===no),duplicate=fresh?.items?.find(x=>partKey(x.name,x.partNo)===partKey(name,'')&&x.status!=='RETURNED');if(duplicate){alert('This part is already on the Parts List. The latest server data has been loaded.');openList(no);return}}const r=addItem(no,{name,qty});if(!r.ok){if(r.reason==='OPEN_LIST_EXISTS'&&r.list){openList(r.list.listNo);return}if(r.reason==='DUPLICATE_PART'){alert('This part is already on the Parts List.');openList(no);return}alert(r.reason);return}const item=r.list.items[r.list.items.length-1],u=currentUser()||{};const synced=await commitEvent({eventId:'spare-item-'+item.id,entityId:item.id,actorId:u.id||null,type:'SPARE_PART_LISTED',serverRevision:1,payload:{partId:item.id,listNo:no,jobCard:r.list.jobCard,name:item.name,partNo:item.partNo,qty:item.qty}});if(!synced.ok&&synced.reason!=='V2_TRANSPORT_UNAVAILABLE')console.warn('Spare part item sync deferred',synced.reason);openList(no)}
